{"plan_json": "{
  "objectives": [
    {
      "id": 1,
      "objective": "Find measured laser-beam attenuation/extinction by plume in LPBF and low-power CW fibre-laser processing",
      "rationale": "Direct measurements of beam loss are the most relevant data for the user's question about whether attenuation is ~0.1% or ~10%",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 2,
      "objective": "Find measured size distributions of condensate in LPBF plumes/fumes (primary particle size, agglomerate size, fractal dimension, variation with height/time)",
      "rationale": "Particle size determines optical cross-section and thus beam attenuation. Need data for SS, Ti-6Al-4V, Ni alloys and Al alloys",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 3,
      "objective": "Find time scales for metal vapour nucleation, coagulation in laser plumes - when do 100-300 nm agglomerates form",
      "rationale": "Critical to know if agglomerates form within the beam path (0.1-1 ms, 1-5 mm above pool)",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 4,
      "objective": "Find published aerosol models of LPBF or laser-welding plumes and predicted particle sizes at 1 ms and 10 ms",
      "rationale": "Modeling work can fill gaps where measurements are unavailable",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 5,
      "objective": "Find composition and optical constants of Al condensate at 1070 nm in LPBF conditions (metallic Al vs Al2O3 vs MgO)",
      "rationale": "Optical properties of the condensate directly determine extinction efficiency",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Find evidence of plasma or inverse-Bremsstrahlung absorption at 1070 nm in LPBF of Al",
      "rationale": "Plasma absorption would be an additional mechanism of beam loss beyond particle scattering",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 7,
      "objective": "Synthesize findings, create summary artifacts, and submit final answer",
      "rationale": "Need to integrate all evidence into a coherent answer addressing all 6 sub-questions",
      "status": "pending",
      "result": null,
      "evaluation": null
    }
  ]
}"}

